// BridgeBase.test.js: BridgeBase > edge cases > large amount requires 1 hour timelock
const { expect } = require("chai");
const { ethers } = require("hardhat");
const { time } = require("@nomicfoundation/hardhat-network-helpers");
const { anyValue } = require("@nomicfoundation/hardhat-chai-matchers/withArgs");
let owner;
let signer1;
let signer2;
let signer3;
let user;
let receiver;
let usdc;
let bridge;
// beforeEach of suite "BridgeBase"
